#!/usr/bin/env python3
"""AI Behaviour Control Lab coordination runtime.

Domain: COORDINATION_RUNTIME 2.1.0
Purpose: fail-closed local coordination primitives for a research/governance project.
GitHub is never treated as canonical state.
"""
from __future__ import annotations
from pathlib import Path
import hashlib, json, os, time, uuid
from contextlib import contextmanager

try:
    import fcntl
except ImportError:  # pragma: no cover
    fcntl = None

PROJECT_ID = "ai-behaviour-control-lab"
REPOSITORY = "boberino93-bit/ai-behaviour-control-lab"
CANONICAL_ROOT = Path("/AI-Behaviour-Control-Lab-AgentBus")
COORDINATION_RUNTIME_VERSION = "2.1.0"
RESEARCH_GOVERNANCE_VERSION = "1.1.1"

class CoordinationError(RuntimeError): pass
class ProjectMismatch(CoordinationError): pass
class RepositoryMismatch(CoordinationError): pass
class PathEscape(CoordinationError): pass
class AuthorizationError(CoordinationError): pass
class DuplicateOperation(CoordinationError): pass
class LeaseConflict(CoordinationError): pass
class StaleWrite(CoordinationError): pass

def assert_project(project_id: str) -> None:
    if project_id != PROJECT_ID:
        raise ProjectMismatch(f"expected {PROJECT_ID}, got {project_id!r}")

def assert_repository(repository: str) -> None:
    if repository != REPOSITORY:
        raise RepositoryMismatch(f"expected {REPOSITORY}, got {repository!r}")

def project_scoped_path(root: Path, relative: str) -> Path:
    root = root.resolve()
    target = (root / relative).resolve()
    if target != root and root not in target.parents:
        raise PathEscape(relative)
    return target

def canonical_payload_hash(payload) -> str:
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    return hashlib.sha256(raw).hexdigest()

@contextmanager
def _locked(lock_path: Path):
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with open(lock_path, "a+b") as f:
        if fcntl is not None:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            if fcntl is not None:
                fcntl.flock(f.fileno(), fcntl.LOCK_UN)

def _read_json(path: Path, default):
    if not path.exists():
        return default
    return json.loads(path.read_text(encoding="utf-8"))

def atomic_write_json(path: Path, value, expected_version=None):
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = path.with_suffix(path.suffix + ".lock")
    with _locked(lock):
        current = _read_json(path, None)
        if expected_version is not None:
            current_version = None if current is None else current.get("version")
            if current_version != expected_version:
                raise StaleWrite(f"expected version {expected_version}, current={current_version}")
        tmp = path.with_name(path.name + f".tmp-{uuid.uuid4().hex}")
        data = json.dumps(value, indent=2, sort_keys=True)
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)

class IdempotencyJournal:
    def __init__(self, path: Path):
        self.path = path
        self.lock = path.with_suffix(path.suffix + ".lock")

    def claim(self, project_id: str, key: str, result_ref: str | None = None) -> bool:
        assert_project(project_id)
        with _locked(self.lock):
            state = _read_json(self.path, {"project_id": PROJECT_ID, "keys": {}})
            if key in state["keys"]:
                return False
            state["keys"][key] = {"claimed_at": time.time(), "result_ref": result_ref}
            atomic_write_json_unlocked(self.path, state)
            return True

def atomic_write_json_unlocked(path: Path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".tmp-{uuid.uuid4().hex}")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(value, f, indent=2, sort_keys=True)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)

class LeaseStore:
    def __init__(self, path: Path):
        self.path = path
        self.lock = path.with_suffix(path.suffix + ".lock")

    def claim(self, project_id: str, resource_id: str, holder: str, ttl_seconds: float, now=None):
        assert_project(project_id)
        now = time.time() if now is None else now
        with _locked(self.lock):
            state = _read_json(self.path, {"project_id": PROJECT_ID, "leases": {}})
            old = state["leases"].get(resource_id)
            if old and old["expires_at"] > now and old["holder"] != holder:
                raise LeaseConflict(resource_id)
            lease = {
                "lease_id": str(uuid.uuid4()), "project_id": PROJECT_ID,
                "resource_id": resource_id, "holder": holder,
                "acquired_at": now, "expires_at": now + ttl_seconds, "status": "ACTIVE"
            }
            state["leases"][resource_id] = lease
            atomic_write_json_unlocked(self.path, state)
            return lease

    def release(self, project_id: str, resource_id: str, holder: str):
        assert_project(project_id)
        with _locked(self.lock):
            state = _read_json(self.path, {"project_id": PROJECT_ID, "leases": {}})
            lease = state["leases"].get(resource_id)
            if not lease:
                return False
            if lease["holder"] != holder:
                raise AuthorizationError("only the holder may release an active lease")
            lease["status"] = "RELEASED"
            lease["expires_at"] = min(lease["expires_at"], time.time())
            atomic_write_json_unlocked(self.path, state)
            return True

def validate_message(message: dict) -> dict:
    required = {
        "schema","message_id","project_id","destination_project_id","sender_agent_id",
        "sender_instance_id","to","kind","timestamp_utc","correlation_id","idempotency_key",
        "payload","payload_sha256"
    }
    missing = required - message.keys()
    if missing:
        raise CoordinationError(f"missing fields: {sorted(missing)}")
    assert_project(message["project_id"])
    assert_project(message["destination_project_id"])
    expected = canonical_payload_hash(message["payload"])
    if message["payload_sha256"] != expected:
        raise CoordinationError("payload hash mismatch")
    if message.get("cross_project_exchange"):
        raise AuthorizationError("ordinary runtime has cross-project exchange disabled")
    return message

def authorize_role(role: str, operation: str) -> None:
    grants = {
        "PRIMARY": {"publish_message","claim_task","write_artifact","review","accept","backup","integrate"},
        "MANAGER": {"publish_message","claim_task","write_artifact","review","recommend"},
        "RESEARCH": {"publish_message","claim_task","write_artifact","research"}
    }
    if operation not in grants.get(role, set()):
        raise AuthorizationError(f"{role} lacks {operation}")

